use vstd::prelude::*;

verus! {

/// Spec view: rotating `list` right by `n` positions.
/// For an index `i` in the output, the element comes from input index
/// `(i + s) % len`, where `s = (len - (n % len)) % len` (a left-rotation by `s`).
pub open spec fn rotate_right_spec(list: Seq<u32>, n: nat) -> Seq<u32>
    recommends list.len() > 0
{
    let len: nat = list.len();
    let r: nat = n % len;
    let s: nat = (len - r) % len;
    Seq::new(len, |i: int| list.index(((i as nat + s) % len) as int))
}

pub fn rotate_right(list: &Vec<u32>, n: usize) -> (out: Vec<u32>)
    requires
        list@.len() > 0,
    ensures
        out@ == rotate_right_spec(list@, n as nat),
{
    let len = list.len();
    debug_assert!(len > 0);

    // s = len - (n mod len)
    let r = n % len;
    let s = (len - r) % len; // handles r == 0 => s == 0

    // result = list[s..len] ++ list[0..s]
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..]);
    new_list.extend_from_slice(&list[..s]);
    new_list
}

} // verus!

